For any $\delta\in(0,1)$, let
\begin{align*} 
n_0 &\asymp \rho^{-1} \cdot (\nu \sigma \tilde{\tau})^2\cdot s^{3} \cdot\log^4\big(kTd/(\delta \lambda)\big),\\
\alpha &= \sigma\nu\sqrt{s\tilde \tau}\cdot\log(\sigma\rho^{-1}dkT/\delta), \
\beta  = \sigma r\sqrt{s\log(kTd/\delta)}.
\end{align*}
Under Assumptions \ref{ass1}-\ref{ass3}, the regret of the actions sequence $\{i_t\}^T_{t=1} $ generated by the \textsc{Sparse-LinUCB} algorithm is upper bounded by  
\begin{align*}
    R_T\big(\{i_t\},\theta^*\big) \lesssim \Big( n_0\beta+ \alpha  \sqrt{sT\log(T)\cdot\big(\lambda+ \log(\sigma dTk/\delta) \big)} + \alpha \sigma \sqrt{T\log(kTd/\delta)}   \Big)\cdot \log(T),
\end{align*} \label{thm:main-upper}
with probability at least $1-\delta$.

For any $\delta\in(0,1)$, let 
\begin{align*} 
    n_0 &\asymp \rho^{-1} \cdot (\nu \sigma \tilde{\tau})^2\cdot s^{3} \cdot\log^4\big(kTd/(\delta \lambda)\big),\\
\beta & = \sigma r \sqrt{s\log(kTd/\delta)},\ \gamma =\sigma(\lambda^{1/2}+\nu+\sigma)\log^{3/2}(kTd/\delta).
\end{align*}
Then under Assumptions \ref{ass1}-\ref{ass3}, the regret of actions sequence $\{i_t\}^T_{t=1} $ generated by the \textsc{Sparse-SupLinUCB} algorithm \vspace{4pt}
 is upper bounded by 
 \begin{align*}
    R_T\big(\{ i_t\},\theta^*\big) &\lesssim  \sqrt{T}+ \Big(n_0\beta+\gamma\sqrt{sT\cdot \log(T)\big(\lambda+ \log(\sigma dTk/\delta) \big)} \Big)\cdot  \log(T)\cdot \log(\beta T),
    \end{align*} \label{thm:suplinucb}
with probability at least $1-\delta$.
